package com.aoo.bcg.gamespi.fsm;
import java.util.List;import java.util.Set;
public final class CommonRoomLifecycle{public enum Event{CONFIGURE,START,PAUSE,RESUME,ROUND_END,SETTLED,FINISH,DISSOLVE_REQUEST,DISSOLVED}private CommonRoomLifecycle(){}public static List<StateTransition<RoomLifecycleState,Event>>transitions(){return List.of(new StateTransition<>(RoomLifecycleState.CREATED,Event.CONFIGURE,RoomLifecycleState.WAITING,"configurationValid","publishWaiting"),new StateTransition<>(RoomLifecycleState.WAITING,Event.START,RoomLifecycleState.PLAYING,"allReady","startRound"),new StateTransition<>(RoomLifecycleState.PLAYING,Event.PAUSE,RoomLifecycleState.PAUSED,"pauseAllowed","freezeTimers"),new StateTransition<>(RoomLifecycleState.PAUSED,Event.RESUME,RoomLifecycleState.PLAYING,"resumeAllowed","resumeTimers"),new StateTransition<>(RoomLifecycleState.PLAYING,Event.ROUND_END,RoomLifecycleState.SETTLING,"roundEnded","settleRound"),new StateTransition<>(RoomLifecycleState.SETTLING,Event.SETTLED,RoomLifecycleState.INTER_ROUND,"settlementCommitted","publishSettlement"),new StateTransition<>(RoomLifecycleState.INTER_ROUND,Event.START,RoomLifecycleState.PLAYING,"nextRoundReady","startRound"),new StateTransition<>(RoomLifecycleState.INTER_ROUND,Event.FINISH,RoomLifecycleState.FINISHED,"roomComplete","closeRoom"),new StateTransition<>(RoomLifecycleState.WAITING,Event.DISSOLVE_REQUEST,RoomLifecycleState.DISSOLVING,"dissolveAllowed","openDissolve"),new StateTransition<>(RoomLifecycleState.DISSOLVING,Event.DISSOLVED,RoomLifecycleState.DISSOLVED,"dissolveApproved","closeRoom"));}public static Set<RoomLifecycleState>terminalStates(){return Set.of(RoomLifecycleState.FINISHED,RoomLifecycleState.DISSOLVED);}}
